import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.Cvf4Fkn6.js";const g=JSON.parse('{"title":"布局自定义","description":"","frontmatter":{},"headers":[],"relativePath":"guide/layouts.md","filePath":"guide/layouts.md","lastUpdated":1794574960000}'),o={name:"guide/layouts.md"};function l(i,t,n,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="布局自定义" tabindex="-1">布局自定义 <a class="header-anchor" href="#布局自定义" aria-label="Permalink to &quot;布局自定义&quot;">​</a></h1><p>WTidy 沿用原版 Window Tidy 的<strong>网格 + 区域</strong>模型：一个布局 = 一套网格密度 + 若干矩形区域。例如「居中」是 6×6 网格上的区域 <code>(2,2)-(5,5)</code>——区域坐标都是网格格子，编辑器里所见即所得。</p><h2 id="内置布局-8-种" tabindex="-1">内置布局（8 种） <a class="header-anchor" href="#内置布局-8-种" aria-label="Permalink to &quot;内置布局（8 种）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>布局</th><th>网格</th><th>说明</th></tr></thead><tbody><tr><td>左右半屏</td><td>2×1</td><td>左、右两个半屏区域</td></tr><tr><td>上下半屏</td><td>1×2</td><td>上、下两个半屏区域</td></tr><tr><td>三等分</td><td>3×1</td><td>左 / 中 / 右三列</td></tr><tr><td>左 1/3 + 右 2/3</td><td>3×1</td><td>双区布局</td></tr><tr><td>左 2/3 + 右 1/3</td><td>3×1</td><td>双区布局</td></tr><tr><td>四分</td><td>2×2</td><td>四宫格</td></tr><tr><td>最大化</td><td>1×1</td><td>铺满整个屏幕</td></tr><tr><td>居中</td><td>6×6</td><td>网格区域 <code>(2,2)-(5,5)</code>，四周留边</td></tr></tbody></table><p>内置布局只是预置数据，可以随意改、删，也可一键恢复默认。</p><h2 id="编辑布局" tabindex="-1">编辑布局 <a class="header-anchor" href="#编辑布局" aria-label="Permalink to &quot;编辑布局&quot;">​</a></h2><p>设置「布局」页双击任一布局（或新增）进入编辑器：</p><ul><li><strong>网格密度</strong>：宽 1–12 × 高 1–12 格</li><li><strong>区域</strong>：在画布上拖出矩形即为一个区域，支持多区域（如「左窄列 + 右上 + 右下」）</li><li><strong>实时预览</strong>：右侧缩略图随时显示当前布局的实际效果</li><li><strong>名称</strong>：布局名显示在图标条标注与菜单栏中</li></ul><h2 id="作用域" tabindex="-1">作用域 <a class="header-anchor" href="#作用域" aria-label="Permalink to &quot;作用域&quot;">​</a></h2><p>每个布局可选<strong>可用屏幕</strong>：所有屏幕（默认）或仅指定某一块显示器——比如只在超宽屏上提供「三等分」，笔记本屏上不出现。对齐原版的 &quot;All Screens&quot; 概念。</p><h2 id="布局列表管理" tabindex="-1">布局列表管理 <a class="header-anchor" href="#布局列表管理" aria-label="Permalink to &quot;布局列表管理&quot;">​</a></h2><p>「布局」页的列表支持：</p><ul><li><strong>拖动排序</strong>——顺序即图标条中图标的顺序</li><li><strong>新增 / 删除</strong>；误删可用「恢复内置布局」找回</li><li><strong>每区域快捷键</strong>：内置布局已预置，列表行内可直接改录（详见<a href="./hotkeys.html#改录与自定义">快捷键</a>）</li></ul>',13)])])}const p=d(o,[["render",l]]);export{g as __pageData,p as default};
